insert into public.translations (locale, key, value) values
  ('pt-BR', 'mcp.apply', $json$"Aplicar"$json$::jsonb),
  ('en', 'mcp.apply', $json$"Apply"$json$::jsonb),
  ('es', 'mcp.apply', $json$"Aplicar"$json$::jsonb),
  ('zh-CN', 'mcp.apply', $json$"应用"$json$::jsonb),
  ('hi', 'mcp.apply', $json$"लागू करें"$json$::jsonb),
  ('ar', 'mcp.apply', $json$"تطبيق"$json$::jsonb),
  ('fr', 'mcp.apply', $json$"Appliquer"$json$::jsonb),
  ('ru', 'mcp.apply', $json$"Применить"$json$::jsonb),
  ('ja', 'mcp.apply', $json$"適用"$json$::jsonb),
  ('de', 'mcp.apply', $json$"Übernehmen"$json$::jsonb),
  ('pt-BR', 'mcp.draft.check', $json$"Lido do que você colou. Aplicar põe o servidor na lista de Configuração › MCP; nada é gravado antes de você clicar em Salvar configuração."$json$::jsonb),
  ('en', 'mcp.draft.check', $json$"Read from what you pasted. Apply puts it in the list in Settings › MCP; nothing is stored until you click Save settings."$json$::jsonb),
  ('es', 'mcp.draft.check', $json$"Leído de lo que pegaste. Aplicar pone el servidor en la lista de Configuración › MCP; no se guarda nada hasta que hagas clic en Guardar configuración."$json$::jsonb),
  ('zh-CN', 'mcp.draft.check', $json$"根据你粘贴的内容读取。“应用”会把它放入“设置 › MCP”的列表；在点击“保存设置”之前不会保存任何内容。"$json$::jsonb),
  ('hi', 'mcp.draft.check', $json$"आपके चिपकाए गए से पढ़ा गया। लागू करें इसे सेटिंग्स › MCP की सूची में डालता है; सेटिंग्स सहेजें पर क्लिक करने से पहले कुछ भी सहेजा नहीं जाता।"$json$::jsonb),
  ('ar', 'mcp.draft.check', $json$"قُرئ مما لصقته. «تطبيق» يضعه في قائمة الإعدادات › MCP؛ ولا يُحفظ شيء قبل أن تنقر «حفظ الإعدادات»."$json$::jsonb),
  ('fr', 'mcp.draft.check', $json$"Lu à partir de ce que vous avez collé. Appliquer l’ajoute à la liste de Configuration › MCP ; rien n’est enregistré avant un clic sur Enregistrer la configuration."$json$::jsonb),
  ('ru', 'mcp.draft.check', $json$"Прочитано из вставленного текста. «Применить» добавляет сервер в список в Настройки › MCP; ничего не сохраняется, пока вы не нажмёте «Сохранить настройки»."$json$::jsonb),
  ('ja', 'mcp.draft.check', $json$"貼り付けた内容から読み取りました。「適用」で設定 › MCP の一覧に入り、「設定を保存」をクリックするまで何も保存されません。"$json$::jsonb),
  ('de', 'mcp.draft.check', $json$"Aus dem Eingefügten gelesen. Übernehmen setzt den Server in die Liste unter Einstellungen › MCP; gespeichert wird erst, wenn Sie auf Einstellungen speichern klicken."$json$::jsonb),
  ('pt-BR', 'mcp.staged', $json$"O servidor MCP está em Configuração › MCP, ainda não salvo: clique em Salvar configuração para mantê-lo ou em Descartar para tirá-lo."$json$::jsonb),
  ('en', 'mcp.staged', $json$"The MCP server is in Settings › MCP, not saved yet: click Save settings to keep it or Discard to drop it."$json$::jsonb),
  ('es', 'mcp.staged', $json$"El servidor MCP está en Configuración › MCP, aún sin guardar: haz clic en Guardar configuración para conservarlo o en Descartar para quitarlo."$json$::jsonb),
  ('zh-CN', 'mcp.staged', $json$"MCP 服务器已在“设置 › MCP”中，但尚未保存：点击“保存设置”保留它，或点击“放弃更改”丢弃它。"$json$::jsonb),
  ('hi', 'mcp.staged', $json$"MCP सर्वर सेटिंग्स › MCP में है, अभी सहेजा नहीं गया: रखने के लिए सेटिंग्स सहेजें पर क्लिक करें या हटाने के लिए बदलाव छोड़ें पर।"$json$::jsonb),
  ('ar', 'mcp.staged', $json$"خادم MCP موجود في الإعدادات › MCP ولم يُحفظ بعد: انقر «حفظ الإعدادات» للإبقاء عليه أو «تجاهل التغييرات» لإزالته."$json$::jsonb),
  ('fr', 'mcp.staged', $json$"Le serveur MCP est dans Configuration › MCP, pas encore enregistré : cliquez sur Enregistrer la configuration pour le garder ou sur Annuler les modifications pour l’écarter."$json$::jsonb),
  ('ru', 'mcp.staged', $json$"Сервер MCP находится в Настройки › MCP, но ещё не сохранён: нажмите «Сохранить настройки», чтобы оставить его, или «Отменить», чтобы убрать."$json$::jsonb),
  ('ja', 'mcp.staged', $json$"MCP サーバーは設定 › MCP に入りましたが、まだ保存されていません。残すには「設定を保存」、取り消すには「破棄」をクリックしてください。"$json$::jsonb),
  ('de', 'mcp.staged', $json$"Der MCP-Server steht unter Einstellungen › MCP, noch nicht gespeichert: Klicken Sie auf Einstellungen speichern, um ihn zu behalten, oder auf Verwerfen, um ihn zu entfernen."$json$::jsonb),
  ('pt-BR', 'settings.notSaved', $json$"Não salvo"$json$::jsonb),
  ('en', 'settings.notSaved', $json$"Not saved"$json$::jsonb),
  ('es', 'settings.notSaved', $json$"Sin guardar"$json$::jsonb),
  ('zh-CN', 'settings.notSaved', $json$"未保存"$json$::jsonb),
  ('hi', 'settings.notSaved', $json$"सहेजा नहीं गया"$json$::jsonb),
  ('ar', 'settings.notSaved', $json$"غير محفوظ"$json$::jsonb),
  ('fr', 'settings.notSaved', $json$"Non enregistré"$json$::jsonb),
  ('ru', 'settings.notSaved', $json$"Не сохранено"$json$::jsonb),
  ('ja', 'settings.notSaved', $json$"未保存"$json$::jsonb),
  ('de', 'settings.notSaved', $json$"Nicht gespeichert"$json$::jsonb),
  ('pt-BR', 'settings.saveHint', $json$"Nada nesta tela vale antes de você clicar em Salvar configuração: Descartar desfaz as mudanças e Restaurar padrões só preenche os valores de partida."$json$::jsonb),
  ('en', 'settings.saveHint', $json$"Nothing on this screen takes effect until you click Save settings: Discard drops the changes and Restore defaults only fills in the starting values."$json$::jsonb),
  ('es', 'settings.saveHint', $json$"Nada en esta pantalla tiene efecto hasta que hagas clic en Guardar configuración: Descartar deshace los cambios y Restaurar valores predeterminados solo rellena los valores iniciales."$json$::jsonb),
  ('zh-CN', 'settings.saveHint', $json$"此页面上的任何改动在点击“保存设置”之前都不会生效：“放弃更改”会撤销改动，“恢复默认值”只是填入初始值。"$json$::jsonb),
  ('hi', 'settings.saveHint', $json$"इस स्क्रीन पर कुछ भी तब तक लागू नहीं होता जब तक आप सेटिंग्स सहेजें पर क्लिक न करें: बदलाव छोड़ें बदलावों को रद्द करता है और डिफ़ॉल्ट बहाल करें सिर्फ़ शुरुआती मान भरता है।"$json$::jsonb),
  ('ar', 'settings.saveHint', $json$"لا يسري شيء في هذه الشاشة حتى تنقر «حفظ الإعدادات»: «تجاهل التغييرات» يلغي التغييرات و«استعادة الإعدادات الافتراضية» يملأ القيم الأولية فقط."$json$::jsonb),
  ('fr', 'settings.saveHint', $json$"Rien sur cet écran ne prend effet avant un clic sur Enregistrer la configuration : Annuler les modifications défait les changements et Rétablir les valeurs par défaut ne fait que remplir les valeurs de départ."$json$::jsonb),
  ('ru', 'settings.saveHint', $json$"Ничего на этом экране не вступает в силу, пока вы не нажмёте «Сохранить настройки»: «Отменить» отбрасывает изменения, а «Восстановить значения по умолчанию» только подставляет исходные значения."$json$::jsonb),
  ('ja', 'settings.saveHint', $json$"この画面の変更は「設定を保存」をクリックするまで反映されません。「破棄」で変更を取り消し、「既定値に戻す」は初期値を入れるだけです。"$json$::jsonb),
  ('de', 'settings.saveHint', $json$"Nichts auf diesem Bildschirm wirkt, bevor Sie auf Einstellungen speichern klicken: Verwerfen macht die Änderungen rückgängig, und Standardwerte wiederherstellen setzt nur die Ausgangswerte ein."$json$::jsonb),
  ('pt-BR', 'project.delete.onSite', $json$"O projeto de uma organização se exclui no site do JayV, pelo owner ou por um maintainer da organização."$json$::jsonb),
  ('en', 'project.delete.onSite', $json$"An organization's project is deleted on the JayV site, by an owner or maintainer of the organization."$json$::jsonb),
  ('es', 'project.delete.onSite', $json$"El proyecto de una organización se elimina en el sitio de JayV, por un owner o maintainer de la organización."$json$::jsonb),
  ('zh-CN', 'project.delete.onSite', $json$"组织的项目需在 JayV 网站上由该组织的 owner 或 maintainer 删除。"$json$::jsonb),
  ('hi', 'project.delete.onSite', $json$"किसी संगठन का प्रोजेक्ट JayV साइट पर, संगठन के owner या maintainer द्वारा हटाया जाता है।"$json$::jsonb),
  ('ar', 'project.delete.onSite', $json$"يُحذف مشروع المؤسسة في موقع JayV، بواسطة مالك المؤسسة أو أحد مشرفيها."$json$::jsonb),
  ('fr', 'project.delete.onSite', $json$"Le projet d’une organisation se supprime sur le site JayV, par un owner ou un maintainer de l’organisation."$json$::jsonb),
  ('ru', 'project.delete.onSite', $json$"Проект организации удаляется на сайте JayV — это делает owner или maintainer организации."$json$::jsonb),
  ('ja', 'project.delete.onSite', $json$"組織のプロジェクトは、JayV サイトで組織の owner または maintainer が削除します。"$json$::jsonb),
  ('de', 'project.delete.onSite', $json$"Das Projekt einer Organisation wird auf der JayV-Website gelöscht, von einem Owner oder Maintainer der Organisation."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.settingsSaveOnly.title', $json$"As configurações só mudam ao salvar"$json$::jsonb),
  ('en', 'whatsNew.item.settingsSaveOnly.title', $json$"Settings change only when you save"$json$::jsonb),
  ('es', 'whatsNew.item.settingsSaveOnly.title', $json$"La configuración solo cambia al guardar"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.settingsSaveOnly.title', $json$"设置只在保存时才会改变"$json$::jsonb),
  ('hi', 'whatsNew.item.settingsSaveOnly.title', $json$"सेटिंग्स सिर्फ़ सहेजने पर बदलती हैं"$json$::jsonb),
  ('ar', 'whatsNew.item.settingsSaveOnly.title', $json$"لا تتغير الإعدادات إلا عند الحفظ"$json$::jsonb),
  ('fr', 'whatsNew.item.settingsSaveOnly.title', $json$"La configuration ne change qu’à l’enregistrement"$json$::jsonb),
  ('ru', 'whatsNew.item.settingsSaveOnly.title', $json$"Настройки меняются только после сохранения"$json$::jsonb),
  ('ja', 'whatsNew.item.settingsSaveOnly.title', $json$"設定は保存したときだけ変わります"$json$::jsonb),
  ('de', 'whatsNew.item.settingsSaveOnly.title', $json$"Einstellungen ändern sich erst beim Speichern"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.settingsSaveOnly.detail', $json$"Nada na tela de configurações vale mais sozinho: idioma, tema, tutoriais, atualizar ao abrir, servidores MCP (ligar, desligar, editar, adicionar, remover) e skills (instalar, ligar, desligar, remover) esperam o Salvar configuração, com a marca Não salvo no que mudou. Descartar desfaz tudo e Restaurar padrões só preenche os valores de partida. Um servidor conferido depois do /mcp no chat vai para Configuração › MCP para ser salvo."$json$::jsonb),
  ('en', 'whatsNew.item.settingsSaveOnly.detail', $json$"Nothing on the Settings screen takes effect by itself anymore: language, theme, tutorials, updating on open, MCP servers (turning on or off, editing, adding, removing) and skills (installing, turning on or off, removing) wait for Save settings, with a Not saved mark on what changed. Discard drops everything and Restore defaults only fills in the starting values. A server reviewed after /mcp in a chat goes to Settings › MCP to be saved."$json$::jsonb),
  ('es', 'whatsNew.item.settingsSaveOnly.detail', $json$"Nada en la pantalla de configuración tiene efecto por sí solo: idioma, tema, tutoriales, actualizar al abrir, servidores MCP (activar, desactivar, editar, añadir, eliminar) y skills (instalar, activar, desactivar, eliminar) esperan a Guardar configuración, con la marca Sin guardar en lo que cambió. Descartar deshace todo y Restaurar valores predeterminados solo rellena los valores iniciales. Un servidor revisado tras /mcp en un chat va a Configuración › MCP para guardarse."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.settingsSaveOnly.detail', $json$"设置页面上的任何内容都不再自动生效：语言、主题、教程、打开时更新、MCP 服务器（开启、关闭、编辑、添加、删除）和技能（安装、开启、关闭、删除）都要等点击“保存设置”，改动处会标有“未保存”。“放弃更改”撤销全部改动，“恢复默认值”只是填入初始值。在聊天中通过 /mcp 确认的服务器会转到“设置 › MCP”等待保存。"$json$::jsonb),
  ('hi', 'whatsNew.item.settingsSaveOnly.detail', $json$"सेटिंग्स स्क्रीन पर अब कुछ भी अपने आप लागू नहीं होता: भाषा, थीम, ट्यूटोरियल, खुलने पर अपडेट, MCP सर्वर (चालू, बंद, संपादित करना, जोड़ना, हटाना) और स्किल (इंस्टॉल, चालू, बंद, हटाना) सेटिंग्स सहेजें का इंतज़ार करते हैं, और जो बदला उस पर सहेजा नहीं गया का निशान होता है। बदलाव छोड़ें सब रद्द करता है और डिफ़ॉल्ट बहाल करें सिर्फ़ शुरुआती मान भरता है। चैट में /mcp के बाद जाँचा गया सर्वर सहेजने के लिए सेटिंग्स › MCP में जाता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.settingsSaveOnly.detail', $json$"لم يعد أي شيء في شاشة الإعدادات يسري من تلقاء نفسه: اللغة والسمة والأدلة والتحديث عند الفتح وخوادم MCP (التشغيل والإيقاف والتعديل والإضافة والإزالة) والمهارات (التثبيت والتشغيل والإيقاف والإزالة) تنتظر «حفظ الإعدادات»، مع علامة «غير محفوظ» على ما تغيّر. «تجاهل التغييرات» يلغي كل شيء و«استعادة الإعدادات الافتراضية» يملأ القيم الأولية فقط. الخادم الذي تراجعه بعد ‎/mcp‎ في المحادثة ينتقل إلى الإعدادات › MCP ليُحفظ."$json$::jsonb),
  ('fr', 'whatsNew.item.settingsSaveOnly.detail', $json$"Plus rien sur l’écran de configuration ne prend effet tout seul : langue, thème, tutoriels, mise à jour à l’ouverture, serveurs MCP (activer, désactiver, modifier, ajouter, supprimer) et skills (installer, activer, désactiver, supprimer) attendent Enregistrer la configuration, avec la mention Non enregistré sur ce qui a changé. Annuler les modifications défait tout et Rétablir les valeurs par défaut ne fait que remplir les valeurs de départ. Un serveur vérifié après /mcp dans un chat va dans Configuration › MCP pour être enregistré."$json$::jsonb),
  ('ru', 'whatsNew.item.settingsSaveOnly.detail', $json$"На экране настроек больше ничего не применяется само: язык, тема, обучение, обновление при запуске, серверы MCP (включение, выключение, изменение, добавление, удаление) и скиллы (установка, включение, выключение, удаление) ждут «Сохранить настройки», а изменённое помечено «Не сохранено». «Отменить» отбрасывает всё, а «Восстановить значения по умолчанию» только подставляет исходные значения. Сервер, проверенный после /mcp в чате, переходит в Настройки › MCP, чтобы его сохранили."$json$::jsonb),
  ('ja', 'whatsNew.item.settingsSaveOnly.detail', $json$"設定画面の変更はもう自動では反映されません。言語、テーマ、チュートリアル、起動時の更新、MCP サーバー（オン／オフ、編集、追加、削除）、スキル（インストール、オン／オフ、削除）は「設定を保存」を待ち、変わったところには「未保存」の印が付きます。「破棄」ですべて取り消し、「既定値に戻す」は初期値を入れるだけです。チャットの /mcp で確認したサーバーは、保存するために設定 › MCP に移ります。"$json$::jsonb),
  ('de', 'whatsNew.item.settingsSaveOnly.detail', $json$"Auf dem Einstellungsbildschirm wirkt nichts mehr von selbst: Sprache, Design, Tutorials, Aktualisieren beim Öffnen, MCP-Server (ein- und ausschalten, bearbeiten, hinzufügen, entfernen) und Skills (installieren, ein- und ausschalten, entfernen) warten auf Einstellungen speichern, mit der Markierung Nicht gespeichert an dem, was sich geändert hat. Verwerfen macht alles rückgängig, und Standardwerte wiederherstellen setzt nur die Ausgangswerte ein. Ein nach /mcp im Chat geprüfter Server landet zum Speichern unter Einstellungen › MCP."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.settingsOwnExtensions.title', $json$"Configurações sem o MCP e as skills da organização"$json$::jsonb),
  ('en', 'whatsNew.item.settingsOwnExtensions.title', $json$"Settings without the organization's MCP and skills"$json$::jsonb),
  ('es', 'whatsNew.item.settingsOwnExtensions.title', $json$"Configuración sin el MCP ni las skills de la organización"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.settingsOwnExtensions.title', $json$"设置中不再显示组织的 MCP 和技能"$json$::jsonb),
  ('hi', 'whatsNew.item.settingsOwnExtensions.title', $json$"सेटिंग्स में संगठन के MCP और स्किल नहीं"$json$::jsonb),
  ('ar', 'whatsNew.item.settingsOwnExtensions.title', $json$"الإعدادات من دون MCP ومهارات المؤسسة"$json$::jsonb),
  ('fr', 'whatsNew.item.settingsOwnExtensions.title', $json$"La configuration sans le MCP ni les skills de l’organisation"$json$::jsonb),
  ('ru', 'whatsNew.item.settingsOwnExtensions.title', $json$"Настройки без MCP и скиллов организации"$json$::jsonb),
  ('ja', 'whatsNew.item.settingsOwnExtensions.title', $json$"設定に組織の MCP とスキルを表示しません"$json$::jsonb),
  ('de', 'whatsNew.item.settingsOwnExtensions.title', $json$"Einstellungen ohne MCP und Skills der Organisation"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.settingsOwnExtensions.detail', $json$"Configuração › MCP e Configuração › Skills listam só os seus servidores e as suas skills. O que uma organização dá fica no ambiente dela, em MCP e Skills no menu lateral."$json$::jsonb),
  ('en', 'whatsNew.item.settingsOwnExtensions.detail', $json$"Settings › MCP and Settings › Skills list only your own servers and skills. What an organization gives is in its environment, under MCP and Skills in its side menu."$json$::jsonb),
  ('es', 'whatsNew.item.settingsOwnExtensions.detail', $json$"Configuración › MCP y Configuración › Skills listan solo tus servidores y tus skills. Lo que da una organización está en su entorno, en MCP y Skills de su menú lateral."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.settingsOwnExtensions.detail', $json$"“设置 › MCP”和“设置 › 技能”只列出你自己的服务器和技能。组织提供的内容在该组织的环境中，位于侧边菜单的 MCP 和技能。"$json$::jsonb),
  ('hi', 'whatsNew.item.settingsOwnExtensions.detail', $json$"सेटिंग्स › MCP और सेटिंग्स › स्किल सिर्फ़ आपके अपने सर्वर और स्किल दिखाते हैं। संगठन जो देता है वह उसके परिवेश में, साइड मेनू के MCP और स्किल में है।"$json$::jsonb),
  ('ar', 'whatsNew.item.settingsOwnExtensions.detail', $json$"تعرض الإعدادات › MCP والإعدادات › المهارات خوادمك ومهاراتك فقط. أما ما تمنحه المؤسسة فهو في بيئتها، ضمن MCP والمهارات في قائمتها الجانبية."$json$::jsonb),
  ('fr', 'whatsNew.item.settingsOwnExtensions.detail', $json$"Configuration › MCP et Configuration › Skills ne listent que vos propres serveurs et skills. Ce qu’une organisation met à disposition est dans son environnement, sous MCP et Skills dans son menu latéral."$json$::jsonb),
  ('ru', 'whatsNew.item.settingsOwnExtensions.detail', $json$"Настройки › MCP и Настройки › Скиллы показывают только ваши собственные серверы и скиллы. То, что даёт организация, находится в её среде, в разделах MCP и Skills бокового меню."$json$::jsonb),
  ('ja', 'whatsNew.item.settingsOwnExtensions.detail', $json$"設定 › MCP と設定 › スキルには、自分のサーバーとスキルだけが表示されます。組織が提供するものは、その組織の環境のサイドメニューにある MCP とスキルにあります。"$json$::jsonb),
  ('de', 'whatsNew.item.settingsOwnExtensions.detail', $json$"Einstellungen › MCP und Einstellungen › Skills listen nur deine eigenen Server und Skills. Was eine Organisation bereitstellt, steht in ihrer Umgebung unter MCP und Skills im Seitenmenü."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"Projetos da organização se excluem no site"$json$::jsonb),
  ('en', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"Organization projects are deleted on the site"$json$::jsonb),
  ('es', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"Los proyectos de la organización se eliminan en el sitio"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"组织的项目改在网站上删除"$json$::jsonb),
  ('hi', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"संगठन के प्रोजेक्ट साइट पर हटाए जाते हैं"$json$::jsonb),
  ('ar', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"مشاريع المؤسسة تُحذف في الموقع"$json$::jsonb),
  ('fr', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"Les projets de l’organisation se suppriment sur le site"$json$::jsonb),
  ('ru', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"Проекты организации удаляются на сайте"$json$::jsonb),
  ('ja', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"組織のプロジェクトはサイトで削除します"$json$::jsonb),
  ('de', 'whatsNew.item.orgProjectDeleteOnSite.title', $json$"Projekte der Organisation werden auf der Website gelöscht"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"No ambiente de uma organização, os projetos não têm mais o botão Excluir: o owner ou um maintainer os exclui no site, na aba Projetos da organização, e eles saem do app de todos os membros que os têm."$json$::jsonb),
  ('en', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"In an organization's environment, projects no longer have a Delete button: an owner or maintainer deletes them on the site, in the organization's Projects tab, and they leave the app of every member who has them."$json$::jsonb),
  ('es', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"En el entorno de una organización, los proyectos ya no tienen el botón Eliminar: un owner o maintainer los elimina en el sitio, en la pestaña Proyectos de la organización, y desaparecen de la app de todos los miembros que los tienen."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"在组织的环境中，项目不再有“删除”按钮：由 owner 或 maintainer 在网站上组织的“项目”标签页中删除，删除后会从所有拥有它们的成员的应用中消失。"$json$::jsonb),
  ('hi', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"संगठन के परिवेश में प्रोजेक्ट में अब हटाएँ बटन नहीं है: owner या maintainer उन्हें साइट पर संगठन के प्रोजेक्ट टैब में हटाते हैं, और वे उन सभी सदस्यों के ऐप से हट जाते हैं जिनके पास वे हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"في بيئة المؤسسة، لم يعد للمشاريع زر «حذف»: يحذفها المالك أو المشرف في الموقع، في تبويب «المشاريع» للمؤسسة، فتختفي من تطبيق كل عضو لديه هذه المشاريع."$json$::jsonb),
  ('fr', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"Dans l’environnement d’une organisation, les projets n’ont plus de bouton Supprimer : un owner ou un maintainer les supprime sur le site, dans l’onglet Projets de l’organisation, et ils disparaissent de l’app de tous les membres qui les ont."$json$::jsonb),
  ('ru', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"В среде организации у проектов больше нет кнопки «Удалить»: owner или maintainer удаляет их на сайте, на вкладке «Проекты» организации, и они исчезают из приложения всех участников, у которых они есть."$json$::jsonb),
  ('ja', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"組織の環境では、プロジェクトに「削除」ボタンがなくなりました。owner または maintainer がサイトの組織の「プロジェクト」タブで削除すると、そのプロジェクトを持つすべてのメンバーのアプリから消えます。"$json$::jsonb),
  ('de', 'whatsNew.item.orgProjectDeleteOnSite.detail', $json$"In der Umgebung einer Organisation haben Projekte keinen Löschen-Button mehr: Ein Owner oder Maintainer löscht sie auf der Website im Tab Projekte der Organisation, und sie verschwinden aus der App aller Mitglieder, die sie haben."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.noWindowScroll.title', $json$"Nada de rolagem fora do conteúdo"$json$::jsonb),
  ('en', 'whatsNew.item.noWindowScroll.title', $json$"No scrolling outside the content"$json$::jsonb),
  ('es', 'whatsNew.item.noWindowScroll.title', $json$"Sin desplazamiento fuera del contenido"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.noWindowScroll.title', $json$"内容之外不再滚动"$json$::jsonb),
  ('hi', 'whatsNew.item.noWindowScroll.title', $json$"सामग्री के बाहर कोई स्क्रॉल नहीं"$json$::jsonb),
  ('ar', 'whatsNew.item.noWindowScroll.title', $json$"لا تمرير خارج المحتوى"$json$::jsonb),
  ('fr', 'whatsNew.item.noWindowScroll.title', $json$"Plus de défilement hors du contenu"$json$::jsonb),
  ('ru', 'whatsNew.item.noWindowScroll.title', $json$"Никакой прокрутки вне содержимого"$json$::jsonb),
  ('ja', 'whatsNew.item.noWindowScroll.title', $json$"内容の外ではスクロールしません"$json$::jsonb),
  ('de', 'whatsNew.item.noWindowScroll.title', $json$"Kein Scrollen außerhalb des Inhalts"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.noWindowScroll.detail', $json$"A janela do JayV não rola nem balança mais inteira: só o conteúdo de cada tela rola, dentro dela."$json$::jsonb),
  ('en', 'whatsNew.item.noWindowScroll.detail', $json$"The JayV window no longer scrolls or bounces as a whole: only the content of each screen scrolls, inside it."$json$::jsonb),
  ('es', 'whatsNew.item.noWindowScroll.detail', $json$"La ventana de JayV ya no se desplaza ni rebota entera: solo se desplaza el contenido de cada pantalla, dentro de ella."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.noWindowScroll.detail', $json$"JayV 窗口不再整体滚动或回弹：只有每个页面的内容在页面内部滚动。"$json$::jsonb),
  ('hi', 'whatsNew.item.noWindowScroll.detail', $json$"JayV की विंडो अब पूरी की पूरी स्क्रॉल या उछलती नहीं है: हर स्क्रीन की सामग्री ही उसके अंदर स्क्रॉल होती है।"$json$::jsonb),
  ('ar', 'whatsNew.item.noWindowScroll.detail', $json$"لم تعد نافذة JayV تتمرر أو ترتد بأكملها: يتمرر محتوى كل شاشة فقط، داخلها."$json$::jsonb),
  ('fr', 'whatsNew.item.noWindowScroll.detail', $json$"La fenêtre de JayV ne défile plus et ne rebondit plus en entier : seul le contenu de chaque écran défile, à l’intérieur."$json$::jsonb),
  ('ru', 'whatsNew.item.noWindowScroll.detail', $json$"Окно JayV больше не прокручивается и не пружинит целиком: прокручивается только содержимое каждого экрана, внутри него."$json$::jsonb),
  ('ja', 'whatsNew.item.noWindowScroll.detail', $json$"JayV のウィンドウ全体がスクロールしたり跳ねたりすることはなくなりました。スクロールするのは各画面の内容だけで、画面の中で動きます。"$json$::jsonb),
  ('de', 'whatsNew.item.noWindowScroll.detail', $json$"Das JayV-Fenster scrollt und federt nicht mehr als Ganzes: Nur der Inhalt jedes Bildschirms scrollt, innerhalb davon."$json$::jsonb),
  ('pt-BR', 'docs.mcp.usage', $json$"Abra Configurações › MCP (ou Ctrl+K › Configurações › MCP) e adicione um servidor pelo formulário ou cole uma configuração (JSON mcpServers, uma linha claude mcp add ou um comando npx). No chat, digite /mcp seguido de uma configuração ou de uma descrição: um agente monta o rascunho e nada é salvo antes de você conferir e clicar em Salvar configuração. Ligar, desligar, editar, adicionar ou remover um servidor só vale ao clicar em Salvar configuração; Descartar desfaz a mudança. Os servidores de uma organização não aparecem aqui, e sim em MCP, no ambiente dela. Depois ligue Aprovar servidores MCP na aba de cada agente que deve usá-los (começa desligado); Ctrl+K › Aprovar servidores MCP faz o mesmo para um agente. As organizações podem bloquear por agente, e o modo planejamento nunca leva os servidores. Quatro servidores oficiais (sequential-thinking, fetch, git e memory) já vêm cadastrados, como entradas que você pode desligar, editar ou remover; fetch e git rodam pelo uvx, então o uv precisa estar instalado. Nos chats de uma organização (o geral e os de cada projeto), os servidores dela valem por cima dos seus com o mesmo nome, mesmo quando a organização desliga um."$json$::jsonb),
  ('en', 'docs.mcp.usage', $json$"Open Settings › MCP (or Ctrl+K › Settings › MCP) and add a server by form, or paste a configuration (mcpServers JSON, a claude mcp add line or an npx command). In a chat, type /mcp followed by a configuration or a description: an agent drafts the configuration and nothing is saved until you review it and click Save settings. Four official servers (sequential-thinking, fetch, git and memory) come registered, as entries you can turn off, edit or remove; fetch and git run through uvx, so uv must be installed. Turning a server on or off, editing, adding or removing it takes effect only when you click Save settings; Discard drops the change. Servers of an organization are not listed here but under MCP in that organization’s environment; in its chats (the general one and each project’s) they win over yours with the same name, even when the organization turns one off. Then turn on Approve MCP servers in the Settings tab of each agent that should use them (it starts off); Ctrl+K › Approve MCP servers does the same for one agent. Organizations can block it per agent, and planning mode never carries the servers."$json$::jsonb),
  ('es', 'docs.mcp.usage', $json$"Abre Configuración › MCP (o Ctrl+K › Configuración › MCP) y añade un servidor con el formulario o pega una configuración (JSON mcpServers, una línea claude mcp add o un comando npx). En un chat, escribe /mcp seguido de una configuración o una descripción: un agente prepara el borrador y no se guarda nada hasta que lo revises y hagas clic en Guardar configuración. Activar, desactivar, editar, añadir o eliminar un servidor solo vale al hacer clic en Guardar configuración; Descartar deshace el cambio. Los servidores de una organización no aparecen aquí, sino en MCP, en el entorno de esa organización. Después activa Aprobar servidores MCP en la pestaña de cada agente que deba usarlos (empieza desactivado); Ctrl+K › Aprobar servidores MCP hace lo mismo para un agente. Las organizaciones pueden bloquearlo por agente, y el modo de planificación nunca lleva los servidores. Cuatro servidores oficiales (sequential-thinking, fetch, git y memory) vienen ya registrados, como entradas que puedes desactivar, editar o eliminar; fetch y git se ejecutan con uvx, así que uv debe estar instalado. En los chats de una organización (el general y los de cada proyecto), sus servidores tienen prioridad sobre los tuyos con el mismo nombre, incluso cuando la organización desactiva uno."$json$::jsonb),
  ('zh-CN', 'docs.mcp.usage', $json$"打开“设置 › MCP”（或 Ctrl+K › 设置 › MCP），通过表单添加服务器，或粘贴配置（mcpServers JSON、claude mcp add 命令行或 npx 命令）。在聊天中输入 /mcp，后面跟配置或描述：代理会生成草稿，在你确认并点击“保存设置”之前不会保存任何内容。开启、关闭、编辑、添加或删除服务器，只有点击“保存设置”后才会生效；“放弃更改”会撤销改动。组织的服务器不在这里显示，而是在该组织环境的 MCP 中。然后在每个要使用它们的代理的设置标签页中开启“批准 MCP 服务器”（默认关闭）；Ctrl+K › 批准 MCP 服务器可对单个代理执行同样的操作。组织可以按代理屏蔽它，规划模式永远不会带上这些服务器。四个官方服务器（sequential-thinking、fetch、git 和 memory）已预先注册，是可以关闭、编辑或删除的普通条目；fetch 和 git 通过 uvx 运行，因此需要安装 uv。在组织的聊天（通用聊天和各项目的聊天）中，组织的服务器优先于你的同名服务器，即使组织将其关闭也一样。"$json$::jsonb),
  ('hi', 'docs.mcp.usage', $json$"सेटिंग › MCP खोलें (या Ctrl+K › सेटिंग › MCP) और फ़ॉर्म से सर्वर जोड़ें या कॉन्फ़िगरेशन चिपकाएँ (mcpServers JSON, claude mcp add पंक्ति या npx कमांड)। चैट में /mcp के बाद कॉन्फ़िगरेशन या विवरण लिखें: एजेंट मसौदा बनाता है और आपके जाँचने और सेटिंग्स सहेजें पर क्लिक करने से पहले कुछ भी सहेजा नहीं जाता। किसी सर्वर को चालू, बंद, संपादित करना, जोड़ना या हटाना सेटिंग्स सहेजें पर क्लिक करने पर ही लागू होता है; बदलाव छोड़ें बदलाव को रद्द करता है। किसी संगठन के सर्वर यहाँ नहीं दिखते, बल्कि उस संगठन के परिवेश में MCP में दिखते हैं। फिर हर उस एजेंट के सेटिंग टैब में MCP सर्वर स्वीकृत करें चालू करें जिसे इन्हें इस्तेमाल करना है (यह बंद से शुरू होता है); Ctrl+K › MCP सर्वर स्वीकृत करें एक एजेंट के लिए यही करता है। संगठन इसे हर एजेंट के लिए अवरुद्ध कर सकते हैं, और योजना मोड कभी सर्वर नहीं ले जाता। चार आधिकारिक सर्वर (sequential-thinking, fetch, git और memory) पहले से रजिस्टर आते हैं, सामान्य प्रविष्टियों के रूप में जिन्हें आप बंद, संपादित या हटा सकते हैं; fetch और git uvx से चलते हैं, इसलिए uv इंस्टॉल होना चाहिए। किसी संगठन की चैट में (सामान्य चैट और हर प्रोजेक्ट की चैट) संगठन के सर्वर आपके उसी नाम वाले सर्वर पर भारी पड़ते हैं, भले ही संगठन उसे बंद कर दे।"$json$::jsonb),
  ('ar', 'docs.mcp.usage', $json$"افتح الإعدادات › MCP (أو Ctrl+K › الإعدادات › MCP) وأضف خادمًا بالنموذج أو الصق إعدادًا (JSON من mcpServers أو سطر claude mcp add أو أمر npx). في المحادثة اكتب ‎/mcp‎ متبوعًا بإعداد أو وصف: يُعدّ الوكيل مسودة ولا يُحفظ شيء قبل أن تراجعه وتنقر «حفظ الإعدادات». لا يسري تشغيل خادم أو إيقافه أو تعديله أو إضافته أو إزالته إلا عند النقر على «حفظ الإعدادات»؛ و«تجاهل التغييرات» يلغي التغيير. لا تظهر خوادم المؤسسة هنا، بل في MCP ضمن بيئة تلك المؤسسة. ثم فعّل «الموافقة على خوادم MCP» في تبويب كل وكيل يجب أن يستخدمها (يبدأ متوقفًا)؛ وCtrl+K › الموافقة على خوادم MCP يفعل الشيء نفسه لوكيل واحد. يمكن للمؤسسات حجبه لكل وكيل، ولا يحمل وضع التخطيط الخوادم أبدًا. تأتي أربعة خوادم رسمية (sequential-thinking وfetch وgit وmemory) مسجَّلة مسبقًا، كإدخالات عادية يمكنك إيقافها أو تعديلها أو إزالتها؛ يعمل fetch وgit عبر uvx، لذا يجب تثبيت uv. في محادثات المؤسسة (العامة ومحادثات كل مشروع) تتقدّم خوادم المؤسسة على خوادمك التي تحمل الاسم نفسه، حتى لو أوقفت المؤسسة أحدها."$json$::jsonb),
  ('fr', 'docs.mcp.usage', $json$"Ouvrez Paramètres › MCP (ou Ctrl+K › Paramètres › MCP) et ajoutez un serveur par le formulaire ou collez une configuration (JSON mcpServers, une ligne claude mcp add ou une commande npx). Dans un chat, tapez /mcp suivi d’une configuration ou d’une description : un agent prépare le brouillon et rien n’est enregistré avant votre vérification et un clic sur Enregistrer la configuration. Activer, désactiver, modifier, ajouter ou supprimer un serveur ne prend effet qu’au clic sur Enregistrer la configuration ; Annuler les modifications défait le changement. Les serveurs d’une organisation n’apparaissent pas ici, mais dans MCP, dans l’environnement de cette organisation. Activez ensuite Approuver les serveurs MCP dans l’onglet de chaque agent qui doit les utiliser (désactivé au départ) ; Ctrl+K › Approuver les serveurs MCP fait de même pour un agent. Les organisations peuvent le bloquer par agent, et le mode planification ne transporte jamais les serveurs. Quatre serveurs officiels (sequential-thinking, fetch, git et memory) sont déjà enregistrés, comme des entrées ordinaires que vous pouvez désactiver, modifier ou supprimer ; fetch et git passent par uvx, donc uv doit être installé. Dans les conversations d’une organisation (la générale et celles de chaque projet), ses serveurs l’emportent sur les vôtres de même nom, même lorsque l’organisation en désactive un."$json$::jsonb),
  ('ru', 'docs.mcp.usage', $json$"Откройте «Настройки › MCP» (или Ctrl+K › Настройки › MCP) и добавьте сервер через форму либо вставьте конфигурацию (JSON mcpServers, строку claude mcp add или команду npx). В чате введите /mcp, а затем конфигурацию или описание: агент подготовит черновик, и ничего не сохранится, пока вы его не проверите и не нажмёте «Сохранить настройки». Включение, выключение, изменение, добавление или удаление сервера вступает в силу только после нажатия «Сохранить настройки»; «Отменить» отбрасывает изменение. Серверы организации здесь не показываются — они в разделе MCP в среде этой организации. Затем включите «Одобрять серверы MCP» на вкладке каждого агента, который должен их использовать (по умолчанию выключено); Ctrl+K › Одобрять серверы MCP делает то же для одного агента. Организации могут блокировать это по агентам, а режим планирования никогда не берёт серверы. Четыре официальных сервера (sequential-thinking, fetch, git и memory) уже зарегистрированы как обычные записи: их можно выключить, изменить или удалить; fetch и git запускаются через uvx, поэтому должен быть установлен uv. В чатах организации (общем и в чатах каждого проекта) её серверы имеют приоритет над вашими с тем же именем, даже если организация выключила сервер."$json$::jsonb),
  ('ja', 'docs.mcp.usage', $json$"設定 › MCP（または Ctrl+K › 設定 › MCP）を開き、フォームでサーバーを追加するか、設定（mcpServers の JSON、claude mcp add の行、npx コマンド）を貼り付けます。チャットでは /mcp に続けて設定または説明を入力します。エージェントが下書きを作り、確認して「設定を保存」をクリックするまで何も保存されません。サーバーのオン／オフ、編集、追加、削除は「設定を保存」をクリックしたときにだけ反映され、「破棄」で変更を取り消せます。組織のサーバーはここには表示されず、その組織の環境の MCP にあります。そのあと、使わせたい各エージェントの設定タブで「MCP サーバーを承認」をオンにします（初期値はオフ）。Ctrl+K › MCP サーバーを承認 で1つのエージェントに対して同じことができます。組織はエージェントごとにブロックでき、計画モードではサーバーは渡されません。 公式サーバー 4 つ（sequential-thinking、fetch、git、memory）が最初から登録されています。通常のエントリなので、オフにしたり編集したり削除したりできます。fetch と git は uvx で動くため、uv のインストールが必要です。組織のチャット（全体用と各プロジェクト用）では、同じ名前なら組織のサーバーがあなたのものより優先されます。組織がそのサーバーをオフにしている場合も同じです。"$json$::jsonb),
  ('de', 'docs.mcp.usage', $json$"Öffnen Sie Einstellungen › MCP (oder Strg+K › Einstellungen › MCP) und fügen Sie einen Server über das Formular hinzu oder fügen Sie eine Konfiguration ein (mcpServers-JSON, eine claude-mcp-add-Zeile oder einen npx-Befehl). Geben Sie im Chat /mcp gefolgt von einer Konfiguration oder Beschreibung ein: Ein Agent erstellt den Entwurf, und nichts wird gespeichert, bevor Sie ihn geprüft und auf Einstellungen speichern geklickt haben. Einen Server ein- oder ausschalten, bearbeiten, hinzufügen oder entfernen wirkt erst mit einem Klick auf Einstellungen speichern; Verwerfen macht die Änderung rückgängig. Die Server einer Organisation stehen nicht hier, sondern unter MCP in der Umgebung dieser Organisation. Schalten Sie danach „MCP-Server freigeben“ im Einstellungs-Tab jedes Agenten ein, der sie nutzen soll (standardmäßig aus); Strg+K › MCP-Server freigeben macht dasselbe für einen Agenten. Organisationen können es je Agent sperren, und der Planungsmodus trägt die Server nie. Vier offizielle Server (sequential-thinking, fetch, git und memory) sind bereits eingetragen, als normale Einträge, die Sie ausschalten, bearbeiten oder entfernen können; fetch und git laufen über uvx, daher muss uv installiert sein. In den Chats einer Organisation (dem allgemeinen und denen jedes Projekts) haben deren Server Vorrang vor Ihren gleichnamigen, auch wenn die Organisation einen ausschaltet."$json$::jsonb),
  ('pt-BR', 'docs.skills.usage', $json$"Abra Configurações › Skills (ou Ctrl+K › Configurações › Skills) e clique em Instalar de uma pasta, escolhendo a pasta de uma skill ou uma pasta com várias; também dá para colar o texto de um SKILL.md. Desligue uma skill para tirá-la da escolha, ou remova-a para apagar a cópia. Cada pedido mostra um passo Skill quando uma foi escolhida. Instalar, ligar, desligar e remover só valem ao clicar em Salvar configuração: a cópia é feita nesse momento, e Descartar desfaz a mudança."$json$::jsonb),
  ('en', 'docs.skills.usage', $json$"Open Settings › Skills (or Ctrl+K › Settings › Skills) and click Install from folder, choosing a skill folder or a folder of skills; you can also paste the text of a SKILL.md. Turn a skill off to take it out of the choice, or remove it to delete the copy. Each request shows a Skill step when one was picked. Installing, turning on or off and removing take effect only when you click Save settings: the copy is made then, and Discard drops the change."$json$::jsonb),
  ('es', 'docs.skills.usage', $json$"Abre Ajustes › Skills (o Ctrl+K › Ajustes › Skills) y haz clic en Instalar desde una carpeta, eligiendo la carpeta de una skill o una carpeta con varias; también puedes pegar el texto de un SKILL.md. Desactiva una skill para sacarla de la elección, o elimínala para borrar la copia. Cada solicitud muestra un paso Skill cuando se eligió una. Instalar, activar, desactivar y eliminar solo valen al hacer clic en Guardar configuración: la copia se hace en ese momento, y Descartar deshace el cambio."$json$::jsonb),
  ('zh-CN', 'docs.skills.usage', $json$"打开“设置 › 技能”（或 Ctrl+K › 设置 › 技能），点击“从文件夹安装”，选择一个技能文件夹或包含多个技能的文件夹；也可以粘贴 SKILL.md 的文本。关闭某个技能可将它移出选择范围，删除则会清除副本。选中技能后，每个请求都会显示“技能”步骤。安装、开启、关闭和删除只有在点击“保存设置”后才会生效：副本在那时才创建，“放弃更改”会撤销改动。"$json$::jsonb),
  ('hi', 'docs.skills.usage', $json$"सेटिंग › स्किल खोलें (या Ctrl+K › सेटिंग › स्किल) और फ़ोल्डर से इंस्टॉल करें पर क्लिक करें, एक स्किल का फ़ोल्डर या कई स्किल वाला फ़ोल्डर चुनें; आप SKILL.md का पाठ भी चिपका सकते हैं। किसी स्किल को चुनाव से हटाने के लिए बंद करें, या प्रति मिटाने के लिए हटाएँ। स्किल चुने जाने पर हर अनुरोध में स्किल चरण दिखता है। इंस्टॉल करना, चालू या बंद करना और हटाना सेटिंग्स सहेजें पर क्लिक करने पर ही लागू होता है: प्रति तभी बनती है, और बदलाव छोड़ें बदलाव को रद्द करता है।"$json$::jsonb),
  ('ar', 'docs.skills.usage', $json$"افتح الإعدادات › المهارات (أو Ctrl+K › الإعدادات › المهارات) وانقر «التثبيت من مجلد»، واختر مجلد مهارة أو مجلدًا يحتوي على عدة مهارات؛ ويمكنك أيضًا لصق نص ملف SKILL.md. أوقف مهارة لإخراجها من الاختيار، أو احذفها لحذف النسخة. يعرض كل طلب خطوة «المهارة» عند اختيار واحدة. لا يسري التثبيت والتشغيل والإيقاف والحذف إلا عند النقر على «حفظ الإعدادات»: تُنشأ النسخة حينها، و«تجاهل التغييرات» يلغي التغيير."$json$::jsonb),
  ('fr', 'docs.skills.usage', $json$"Ouvrez Réglages › Skills (ou Ctrl+K › Réglages › Skills) et cliquez sur Installer depuis un dossier, en choisissant le dossier d’une skill ou un dossier de skills ; vous pouvez aussi coller le texte d’un SKILL.md. Désactivez une skill pour l’écarter du choix, ou supprimez-la pour effacer la copie. Chaque demande affiche une étape Skill quand une a été choisie. Installer, activer, désactiver et supprimer ne prennent effet qu’au clic sur Enregistrer la configuration : la copie est faite à ce moment-là, et Annuler les modifications défait le changement."$json$::jsonb),
  ('ru', 'docs.skills.usage', $json$"Откройте Настройки › Скиллы (или Ctrl+K › Настройки › Скиллы) и нажмите «Установить из папки», выбрав папку скилла или папку со скиллами; можно также вставить текст SKILL.md. Отключите скилл, чтобы убрать его из выбора, или удалите, чтобы стереть копию. Если скилл выбран, в запросе появляется шаг «Скилл». Установка, включение, выключение и удаление вступают в силу только после нажатия «Сохранить настройки»: копия создаётся в этот момент, а «Отменить» отбрасывает изменение."$json$::jsonb),
  ('ja', 'docs.skills.usage', $json$"設定 › スキル（または Ctrl+K › 設定 › スキル）を開き、「フォルダからインストール」をクリックして、スキルのフォルダまたは複数のスキルを含むフォルダを選びます。SKILL.md のテキストを貼り付けることもできます。スキルをオフにすると選択対象から外れ、削除するとコピーが消えます。スキルが選ばれると、各リクエストに「スキル」のステップが表示されます。インストール、オン／オフ、削除は「設定を保存」をクリックしたときにだけ反映されます。コピーはそのときに作られ、「破棄」で変更を取り消せます。"$json$::jsonb),
  ('de', 'docs.skills.usage', $json$"Öffne Einstellungen › Skills (oder Strg+K › Einstellungen › Skills) und klicke auf Aus Ordner installieren; wähle einen Skill-Ordner oder einen Ordner mit Skills; du kannst auch den Text einer SKILL.md einfügen. Schalte einen Skill aus, um ihn aus der Auswahl zu nehmen, oder entferne ihn, um die Kopie zu löschen. Jede Anfrage zeigt einen Skill-Schritt, wenn einer gewählt wurde. Installieren, Ein- und Ausschalten und Entfernen wirken erst, wenn du auf Einstellungen speichern klickst: Erst dann wird kopiert, und Verwerfen macht die Änderung rückgängig."$json$::jsonb),
  ('pt-BR', 'docs.skillsHub.usage', $json$"Abra Configurações › Skills (ou Ctrl+K › Instalar do skills.sh), digite o que você precisa e clique em Buscar; depois clique em Instalar num resultado. Ao clicar em Salvar configuração, o JayV baixa a skill do repositório dela no GitHub e a instala como qualquer skill de uma pasta: desligue ou remova quando quiser, e o Jev a escolhe nos pedidos em que ela serve. No site, owners e maintainers fazem o mesmo na aba Skills da organização, que instala o SKILL.md da skill para todos os membros. Leia as instruções de uma skill antes de instalá-la."$json$::jsonb),
  ('en', 'docs.skillsHub.usage', $json$"Open Settings › Skills (or Ctrl+K › Install from skills.sh), type what you need and press Search, then Install on a result. When you click Save settings, JayV downloads the skill from its GitHub repository and installs it like any skill from a folder: turn it off or remove it whenever you want, and Jev picks it for the requests it fits. On the site, owners and maintainers do the same in the organization’s Skills tab, which installs the skill’s SKILL.md for every member. Read a skill’s instructions before installing it."$json$::jsonb),
  ('es', 'docs.skillsHub.usage', $json$"Abre Configuración › Skills (o Ctrl+K › Instalar desde skills.sh), escribe lo que necesitas y pulsa Buscar; luego pulsa Instalar en un resultado. Al hacer clic en Guardar configuración, JayV descarga la skill de su repositorio de GitHub y la instala como cualquier skill de una carpeta: desactívala o elimínala cuando quieras, y Jev la elige en las solicitudes a las que encaja. En el sitio, owners y maintainers hacen lo mismo en la pestaña Skills de la organización, que instala el SKILL.md de la skill para todos los miembros. Lee las instrucciones de una skill antes de instalarla."$json$::jsonb),
  ('zh-CN', 'docs.skillsHub.usage', $json$"打开“设置 › 技能”（或 Ctrl+K › 从 skills.sh 安装），输入你需要的内容并点击搜索，然后在结果上点击安装。点击“保存设置”后，JayV 会从技能的 GitHub 仓库下载并像文件夹中的技能一样安装：可随时关闭或删除，Jev 会在合适的请求中选用它。在网站上，所有者和维护者可在组织的“技能”标签页做同样的事，为每位成员安装该技能的 SKILL.md。安装前请先阅读技能的说明。"$json$::jsonb),
  ('hi', 'docs.skillsHub.usage', $json$"सेटिंग › स्किल खोलें (या Ctrl+K › skills.sh से इंस्टॉल करें), जो चाहिए वह लिखकर खोजें दबाएँ, फिर किसी परिणाम पर इंस्टॉल करें दबाएँ। सेटिंग्स सहेजें पर क्लिक करने पर JayV स्किल को उसकी GitHub रिपॉज़िटरी से डाउनलोड करता है और फ़ोल्डर की किसी भी स्किल की तरह इंस्टॉल करता है: जब चाहें बंद या हटाएँ, और Jev उसे उन अनुरोधों के लिए चुनता है जिनमें वह फिट बैठती है। साइट पर ओनर और मेंटेनर संगठन के स्किल टैब में यही करते हैं, जो हर सदस्य के लिए स्किल का SKILL.md इंस्टॉल करता है। इंस्टॉल करने से पहले स्किल के निर्देश पढ़ें।"$json$::jsonb),
  ('ar', 'docs.skillsHub.usage', $json$"افتح الإعدادات › المهارات (أو Ctrl+K › التثبيت من skills.sh)، واكتب ما تحتاجه واضغط بحث، ثم اضغط تثبيت على إحدى النتائج. عند النقر على «حفظ الإعدادات» ينزّل JayV المهارة من مستودعها على GitHub ويثبّتها كأي مهارة من مجلد: أوقفها أو أزلها متى شئت، ويختارها Jev للطلبات التي تناسبها. في الموقع يفعل المالكون والمشرفون الأمر نفسه في تبويب المهارات للمؤسسة، فيثبّت ملف SKILL.md للمهارة لجميع الأعضاء. اقرأ تعليمات المهارة قبل تثبيتها."$json$::jsonb),
  ('fr', 'docs.skillsHub.usage', $json$"Ouvrez Paramètres › Skills (ou Ctrl+K › Installer depuis skills.sh), tapez ce dont vous avez besoin et appuyez sur Rechercher, puis sur Installer pour un résultat. Au clic sur Enregistrer la configuration, JayV télécharge la skill depuis son dépôt GitHub et l’installe comme toute skill d’un dossier : désactivez-la ou supprimez-la quand vous voulez, et Jev la choisit pour les demandes qui lui conviennent. Sur le site, les owners et maintainers font de même dans l’onglet Skills de l’organisation, qui installe le SKILL.md de la skill pour tous les membres. Lisez les instructions d’une skill avant de l’installer."$json$::jsonb),
  ('ru', 'docs.skillsHub.usage', $json$"Откройте «Настройки › Навыки» (или Ctrl+K › Установить из skills.sh), введите, что нужно, нажмите «Найти», затем «Установить» у результата. После нажатия «Сохранить настройки» JayV скачивает навык из его репозитория GitHub и устанавливает как любой навык из папки: выключайте или удаляйте когда угодно, а Jev выбирает его для подходящих запросов. На сайте владельцы и мейнтейнеры делают то же на вкладке «Навыки» организации, где SKILL.md навыка устанавливается для всех участников. Прочитайте инструкции навыка перед установкой."$json$::jsonb),
  ('ja', 'docs.skillsHub.usage', $json$"設定 › スキル（または Ctrl+K › skills.sh からインストール）を開き、必要なものを入力して検索を押し、結果の「インストール」を押します。「設定を保存」をクリックすると、JayV はスキルを GitHub リポジトリからダウンロードし、フォルダーのスキルと同じようにインストールします。いつでもオフにしたり削除したりでき、Jev は合うリクエストで選びます。サイトでは、オーナーとメンテナーが組織の「スキル」タブで同じ操作をでき、全メンバー向けにそのスキルの SKILL.md がインストールされます。インストール前にスキルの指示を読んでください。"$json$::jsonb),
  ('de', 'docs.skillsHub.usage', $json$"Öffnen Sie Einstellungen › Skills (oder Strg+K › Von skills.sh installieren), geben Sie ein, was Sie brauchen, drücken Sie Suchen und dann bei einem Ergebnis Installieren. Beim Klick auf Einstellungen speichern lädt JayV den Skill aus seinem GitHub-Repository herunter und installiert ihn wie jeden Skill aus einem Ordner: Schalten Sie ihn jederzeit aus oder entfernen Sie ihn, und Jev wählt ihn für passende Anfragen. Auf der Website tun Owner und Maintainer dasselbe im Skills-Tab der Organisation, der die SKILL.md des Skills für alle Mitglieder installiert. Lesen Sie die Anweisungen eines Skills, bevor Sie ihn installieren."$json$::jsonb),
  ('pt-BR', 'docs.orgExtensions.summary', $json$"O owner e os maintainers configuram servidores MCP e skills da organização no site do JayV, e todo membro os recebe no app, somados aos seus. No app aparecem no ambiente da organização, em MCP e Skills no menu lateral dela, separados das suas Configurações, e não se editam ali; nos projetos da organização os agentes recebem os servidores e o Jev pode escolher as skills."$json$::jsonb),
  ('en', 'docs.orgExtensions.summary', $json$"Owners and maintainers set up MCP servers and skills for the organization on the JayV site, and every member receives them in the app on top of their own. In the app they are listed in the organization's environment, under MCP and Skills in its side menu, apart from your Settings, and cannot be edited there; in the projects of the organization the agents get the servers and Jev can pick the skills."$json$::jsonb),
  ('es', 'docs.orgExtensions.summary', $json$"Los owners y maintainers configuran servidores MCP y skills de la organización en el sitio de JayV, y cada miembro los recibe en la app, además de los suyos. En la app aparecen en el entorno de la organización, en MCP y Skills de su menú lateral, separados de tus Ajustes, y no se pueden editar allí; en los proyectos de la organización los agentes reciben los servidores y Jev puede elegir las skills."$json$::jsonb),
  ('zh-CN', 'docs.orgExtensions.summary', $json$"owner 和 maintainer 在 JayV 网站上为组织设置 MCP 服务器和技能，每位成员都会在应用中收到，并与自己的并用。在应用中，它们显示在该组织环境侧边菜单的 MCP 和技能中，与你自己的设置分开，无法在那里编辑；在组织的项目中，智能体会获得这些服务器，Jev 也可以选用这些技能。"$json$::jsonb),
  ('hi', 'docs.orgExtensions.summary', $json$"owner और maintainer JayV साइट पर संगठन के लिए MCP सर्वर और स्किल्स सेट करते हैं, और हर सदस्य को ये ऐप में अपनी चीज़ों के साथ मिलते हैं। ऐप में ये आपकी सेटिंग्स से अलग, संगठन के परिवेश के साइड मेनू में MCP और स्किल्स में दिखते हैं और वहाँ बदले नहीं जा सकते; संगठन के प्रोजेक्ट में एजेंटों को सर्वर मिलते हैं और Jev स्किल्स चुन सकता है।"$json$::jsonb),
  ('ar', 'docs.orgExtensions.summary', $json$"يضبط owner وmaintainer خوادم MCP ومهارات المؤسسة في موقع JayV، ويتلقاها كل عضو في التطبيق بالإضافة إلى ما لديه. تظهر في التطبيق ضمن بيئة المؤسسة، في MCP والمهارات في قائمتها الجانبية، بمعزل عن إعداداتك، ولا يمكن تعديلها هناك؛ وفي مشاريع المؤسسة تحصل الوكلاء على الخوادم ويمكن لـ Jev اختيار المهارات."$json$::jsonb),
  ('fr', 'docs.orgExtensions.summary', $json$"Les owners et maintainers configurent les serveurs MCP et les skills de l’organisation sur le site JayV, et chaque membre les reçoit dans l’app, en plus des siens. Dans l’app, ils apparaissent dans l’environnement de l’organisation, sous MCP et Skills dans son menu latéral, à part de vos Réglages, et ne s’y modifient pas ; dans les projets de l’organisation, les agents reçoivent les serveurs et Jev peut choisir les skills."$json$::jsonb),
  ('ru', 'docs.orgExtensions.summary', $json$"Owner и maintainer настраивают MCP-серверы и скиллы организации на сайте JayV, и каждый участник получает их в приложении в дополнение к своим. В приложении они показаны в среде организации, в разделах MCP и Skills её бокового меню, отдельно от ваших настроек, и там не изменяются; в проектах организации агенты получают серверы, а Jev может выбирать скиллы."$json$::jsonb),
  ('ja', 'docs.orgExtensions.summary', $json$"owner と maintainer が JayV サイトで組織の MCP サーバーとスキルを設定し、すべてのメンバーが自分のものに加えてアプリで受け取ります。アプリでは、自分の設定とは別に、組織の環境のサイドメニューにある MCP とスキルに表示され、そこでは編集できません。組織のプロジェクトでは、エージェントがサーバーを受け取り、Jev がスキルを選べます。"$json$::jsonb),
  ('de', 'docs.orgExtensions.summary', $json$"Owner und Maintainer richten die MCP-Server und Skills der Organisation auf der JayV-Website ein, und jedes Mitglied erhält sie in der App zusätzlich zu den eigenen. In der App erscheinen sie in der Umgebung der Organisation, unter MCP und Skills in ihrem Seitenmenü, getrennt von deinen Einstellungen, und lassen sich dort nicht bearbeiten; in den Projekten der Organisation erhalten die Agenten die Server und Jev kann die Skills auswählen."$json$::jsonb),
  ('pt-BR', 'docs.orgExtensions.usage', $json$"No site, abra a organização e use as abas Servidores MCP e Skills: adicione um servidor pelo formulário ou colando um JSON mcpServers, ou cole o texto de um SKILL.md, e ligue ou desligue cada um. No Ctrl+K, escolha “gerenciar servidores MCP” ou “gerenciar skills” de uma organização para abrir a aba dela no site. Os servidores podem levar tokens: no site só owners e maintainers os veem e eles chegam apenas ao app dos membros. A mudança chega na próxima sincronização. No app, o que a organização dá aparece só no ambiente dela, em MCP e Skills no menu lateral (só leitura), nunca em Configurações; owner e maintainer ganham um botão que abre a aba correspondente no site."$json$::jsonb),
  ('en', 'docs.orgExtensions.usage', $json$"On the site, open the organization and use the MCP servers and Skills tabs: add a server by form or by pasting an mcpServers JSON, or paste the text of a SKILL.md, and turn each one on or off. In Ctrl+K, choose \"manage MCP servers\" or \"manage skills\" for an organization to open its site tab. Servers can carry tokens, so only owners and maintainers see them on the site and they reach only the members' apps. The change arrives at the next sync. In the app, what the organization gives is listed only in its environment, under MCP and Skills in the side menu (read-only), never in Settings; owners and maintainers get a button to open the matching site tab."$json$::jsonb),
  ('es', 'docs.orgExtensions.usage', $json$"En el sitio, abre la organización y usa las pestañas Servidores MCP y Skills: añade un servidor con el formulario o pegando un JSON mcpServers, o pega el texto de un SKILL.md, y activa o desactiva cada uno. En Ctrl+K, elige «gestionar servidores MCP» o «gestionar skills» de una organización para abrir su pestaña en el sitio. Los servidores pueden llevar tokens: en el sitio solo los ven los owners y maintainers y llegan únicamente a la app de los miembros. El cambio llega en la próxima sincronización. En la app, lo que da la organización aparece solo en su entorno, en MCP y Skills del menú lateral (solo lectura), nunca en Ajustes; owner y maintainer tienen un botón que abre la pestaña correspondiente en el sitio."$json$::jsonb),
  ('zh-CN', 'docs.orgExtensions.usage', $json$"在网站上打开组织，使用“MCP 服务器”和“技能”标签页：通过表单或粘贴 mcpServers JSON 添加服务器，或粘贴 SKILL.md 的内容，并可逐个开启或关闭。在 Ctrl+K 中选择某个组织的“管理 MCP 服务器”或“管理技能”，即可打开它在网站上的标签页。服务器可能包含令牌：在网站上只有 owner 和 maintainer 能看到，并且只会发送给成员的应用。更改会在下次同步时到达。 在应用中，组织提供的内容只在该组织的环境中列出，位于侧边菜单的 MCP 和技能（只读），不会出现在设置里；所有者和维护者有按钮可打开网站上对应的标签页。"$json$::jsonb),
  ('hi', 'docs.orgExtensions.usage', $json$"साइट पर संगठन खोलें और MCP सर्वर और स्किल्स टैब इस्तेमाल करें: फ़ॉर्म से या mcpServers JSON चिपकाकर सर्वर जोड़ें, या SKILL.md का पाठ चिपकाएँ, और हर एक को चालू या बंद करें। Ctrl+K में किसी संगठन के लिए “MCP सर्वर प्रबंधित करें” या “स्किल्स प्रबंधित करें” चुनकर उसका साइट टैब खोलें। सर्वर में टोकन हो सकते हैं: साइट पर इन्हें केवल owner और maintainer देखते हैं और ये सिर्फ़ सदस्यों के ऐप तक पहुँचते हैं। बदलाव अगले सिंक में पहुँचता है। ऐप में संगठन द्वारा दी गई चीज़ें सिर्फ़ उसके परिवेश में, साइड मेनू के MCP और स्किल (केवल पढ़ने के लिए) में दिखती हैं, सेटिंग्स में कभी नहीं; ओनर और मेंटेनर को साइट का संबंधित टैब खोलने वाला बटन मिलता है।"$json$::jsonb),
  ('ar', 'docs.orgExtensions.usage', $json$"في الموقع افتح المؤسسة واستخدم تبويبي خوادم MCP وSkills: أضف خادمًا عبر النموذج أو بلصق JSON الخاص بـ mcpServers، أو الصق نص SKILL.md، وفعّل كل واحد أو عطّله. في Ctrl+K اختر «إدارة خوادم MCP» أو «إدارة المهارات» لمؤسسة ما لفتح تبويبها في الموقع. قد تحمل الخوادم رموزًا: في الموقع لا يراها إلا owner وmaintainer ولا تصل إلا إلى تطبيق الأعضاء. يصل التغيير عند المزامنة التالية. في التطبيق، لا يظهر ما تمنحه المؤسسة إلا في بيئتها، ضمن MCP والمهارات في القائمة الجانبية (للقراءة فقط)، ولا يظهر أبدًا في الإعدادات؛ ويحصل المالك والمشرف على زر يفتح التبويب المقابل في الموقع."$json$::jsonb),
  ('fr', 'docs.orgExtensions.usage', $json$"Sur le site, ouvrez l’organisation et utilisez les onglets Serveurs MCP et Skills : ajoutez un serveur par le formulaire ou en collant un JSON mcpServers, ou collez le texte d’un SKILL.md, et activez ou désactivez chacun. Dans Ctrl+K, choisissez « gérer les serveurs MCP » ou « gérer les skills » d’une organisation pour ouvrir son onglet sur le site. Les serveurs peuvent contenir des jetons : sur le site, seuls les owners et maintainers les voient et ils n’arrivent qu’à l’app des membres. Le changement arrive à la prochaine synchronisation. Dans l’app, ce que l’organisation met à disposition n’apparaît que dans son environnement, sous MCP et Skills dans le menu latéral (lecture seule), jamais dans Réglages ; owners et maintainers ont un bouton qui ouvre l’onglet correspondant du site."$json$::jsonb),
  ('ru', 'docs.orgExtensions.usage', $json$"На сайте откройте организацию и используйте вкладки «MCP-серверы» и «Скиллы»: добавьте сервер через форму или вставив JSON mcpServers, либо вставьте текст SKILL.md, и включайте или отключайте каждый. В Ctrl+K выберите «управление MCP-серверами» или «управление скиллами» организации, чтобы открыть её вкладку на сайте. В серверах могут быть токены: на сайте их видят только owner и maintainer, а попадают они только в приложение участников. Изменение приходит при следующей синхронизации. В приложении то, что даёт организация, показано только в её среде, в разделах MCP и Skills бокового меню (только чтение), и никогда в настройках; у owner и maintainer есть кнопка, открывающая соответствующую вкладку на сайте."$json$::jsonb),
  ('ja', 'docs.orgExtensions.usage', $json$"サイトで組織を開き、「MCP サーバー」と「スキル」タブを使います。フォームまたは mcpServers の JSON を貼り付けてサーバーを追加するか、SKILL.md のテキストを貼り付け、それぞれをオン／オフします。Ctrl+K で組織の「MCP サーバーを管理」または「スキルを管理」を選ぶと、サイトのそのタブが開きます。サーバーにはトークンが含まれる場合があるため、サイトでは owner と maintainer だけが見え、メンバーのアプリにだけ届きます。変更は次回の同期で届きます。 アプリでは、組織が提供するものはその組織の環境のサイドメニューにある MCP と Skills（読み取り専用）にだけ表示され、設定には表示されません。owner と maintainer には、サイトの対応するタブを開くボタンが表示されます。"$json$::jsonb),
  ('de', 'docs.orgExtensions.usage', $json$"Öffne auf der Website die Organisation und nutze die Tabs MCP-Server und Skills: Füge einen Server per Formular oder durch Einfügen eines mcpServers-JSON hinzu oder füge den Text einer SKILL.md ein und schalte jeden ein oder aus. Wähle in Strg+K „MCP-Server verwalten“ oder „Skills verwalten“ einer Organisation, um ihren Tab auf der Website zu öffnen. Server können Tokens enthalten: Auf der Website sehen nur Owner und Maintainer sie, und sie erreichen nur die App der Mitglieder. Die Änderung kommt bei der nächsten Synchronisierung an. In der App erscheint, was die Organisation bereitstellt, nur in ihrer Umgebung, unter MCP und Skills im Seitenmenü (nur lesen), nie in den Einstellungen; Owner und Maintainer erhalten einen Button, der den passenden Tab auf der Website öffnet."$json$::jsonb),
  ('pt-BR', 'docs.orgRepositories.usage', $json$"No site, abra a organização, vá em Repositórios, conecte um provedor e adicione os repositórios. No app, Repositórios, no menu lateral da organização, os lista conforme mudam: escolha a pasta da organização, clone o que falta e use Procurar clones para comparar a pasta inteira, em qualquer profundidade, com a lista do site. No GitHub, conectar instala o GitHub App do JayV na conta ou na organização que você escolher, e ele alcança só os repositórios que você marcar lá; para adicionar outros, clique em GitHub de novo. Um projeto da organização não se exclui no app: o owner ou um maintainer o exclui no site, na aba Projetos da organização, e ele sai do app de todos os membros que o têm, com os chats, enquanto o repositório continua na organização."$json$::jsonb),
  ('en', 'docs.orgRepositories.usage', $json$"On the site, open the organization, go to Repositories, connect a provider and add the repositories. In the app, Repositories in the organization's side menu lists them as they change: choose the organization folder, clone what is missing, and use Find clones to compare the whole folder, at any depth, with the list from the site. On GitHub, connecting installs the JayV GitHub App on the account or organization you choose, and it reaches only the repositories you pick there; to add more, click GitHub again. A project of the organization is not deleted in the app: an owner or maintainer deletes it on the site, in the organization's Projects tab, and it leaves the app of every member who has it, with its chats, while the repository stays in the organization."$json$::jsonb),
  ('es', 'docs.orgRepositories.usage', $json$"En el sitio, abre la organización, ve a Repositorios, conecta un proveedor y añade los repositorios. En la app, Repositorios, en el menú lateral de la organización, los lista a medida que cambian: elige la carpeta de la organización, clona lo que falta y usa Buscar clones para comparar toda la carpeta, a cualquier profundidad, con la lista del sitio. En GitHub, conectar instala la GitHub App de JayV en la cuenta o la organización que elijas, y solo alcanza los repositorios que marques allí; para añadir otros, vuelve a hacer clic en GitHub. Un proyecto de la organización no se elimina en la app: un owner o maintainer lo elimina en el sitio, en la pestaña Proyectos de la organización, y desaparece de la app de todos los miembros que lo tienen, con sus chats, mientras el repositorio sigue en la organización."$json$::jsonb),
  ('zh-CN', 'docs.orgRepositories.usage', $json$"在网站上打开组织，进入“仓库”，连接提供方并添加仓库。在应用中，组织侧边菜单里的“仓库”会随变化实时列出它们：选择组织文件夹，克隆缺少的仓库，并用“查找克隆”在所有层级中将整个文件夹与网站上的列表进行对比。在 GitHub 上，连接会把 JayV 的 GitHub App 安装到你选择的账户或组织，它只能访问你在那里勾选的仓库；要添加更多，请再次点击 GitHub。组织的项目不能在应用中删除：由 owner 或 maintainer 在网站上组织的“项目”标签页中删除，之后它会连同聊天一起从所有拥有它的成员的应用中消失，而仓库仍保留在组织中。"$json$::jsonb),
  ('hi', 'docs.orgRepositories.usage', $json$"साइट पर संगठन खोलें, रिपॉज़िटरी में जाएँ, कोई प्रदाता कनेक्ट करें और रिपॉज़िटरी जोड़ें। ऐप में संगठन के साइड मेनू का रिपॉज़िटरी बदलाव होते ही इन्हें दिखाता है: संगठन का फ़ोल्डर चुनें, जो नहीं है उसे क्लोन करें और क्लोन खोजें से पूरे फ़ोल्डर की, हर गहराई तक, साइट की सूची से तुलना करें। GitHub पर कनेक्ट करने से JayV का GitHub App आपके चुने हुए खाते या संगठन में इंस्टॉल होता है, और वह सिर्फ़ उन्हीं रिपॉज़िटरी तक पहुँचता है जो आप वहाँ चुनते हैं; और जोड़ने के लिए GitHub पर फिर क्लिक करें। संगठन का प्रोजेक्ट ऐप में नहीं हटाया जाता: owner या maintainer उसे साइट पर संगठन के प्रोजेक्ट टैब में हटाते हैं, और वह अपनी चैट के साथ उन सभी सदस्यों के ऐप से हट जाता है जिनके पास वह है, जबकि रिपॉज़िटरी संगठन में बनी रहती है।"$json$::jsonb),
  ('ar', 'docs.orgRepositories.usage', $json$"في الموقع، افتح المؤسسة واذهب إلى المستودعات واربط مزوّدًا وأضف المستودعات. في التطبيق، تعرضها صفحة المستودعات في القائمة الجانبية للمؤسسة كلما تغيّرت: اختر مجلد المؤسسة، واستنسخ ما ينقص، واستخدم البحث عن النسخ لمقارنة المجلد كله، على كل المستويات، بقائمة الموقع. في GitHub، يؤدي الربط إلى تثبيت تطبيق GitHub الخاص بـ JayV في الحساب أو المؤسسة التي تختارها، ولا يصل إلا إلى المستودعات التي تحددها هناك؛ لإضافة المزيد، انقر على GitHub مرة أخرى. لا يُحذف مشروع المؤسسة من التطبيق: يحذفه المالك أو المشرف في الموقع، في تبويب «المشاريع» للمؤسسة، فيختفي مع محادثاته من تطبيق كل عضو لديه، بينما يبقى المستودع في المؤسسة."$json$::jsonb),
  ('fr', 'docs.orgRepositories.usage', $json$"Sur le site, ouvrez l'organisation, allez dans Dépôts, connectez un fournisseur et ajoutez les dépôts. Dans l'application, Dépôts, dans le menu latéral de l'organisation, les liste au fil des changements : choisissez le dossier de l'organisation, clonez ce qui manque et utilisez Chercher des clones pour comparer tout le dossier, à toute profondeur, à la liste du site. Sur GitHub, la connexion installe la GitHub App de JayV sur le compte ou l'organisation de votre choix, et elle n'atteint que les dépôts que vous y cochez ; pour en ajouter d'autres, cliquez à nouveau sur GitHub. Un projet de l'organisation ne se supprime pas dans l'application : un owner ou un maintainer le supprime sur le site, dans l'onglet Projets de l'organisation, et il disparaît de l'application de tous les membres qui l'ont, avec ses conversations, tandis que le dépôt reste dans l'organisation."$json$::jsonb),
  ('ru', 'docs.orgRepositories.usage', $json$"На сайте откройте организацию, перейдите в «Репозитории», подключите провайдера и добавьте репозитории. В приложении раздел «Репозитории» в боковом меню организации показывает их по мере изменений: выберите папку организации, клонируйте недостающие и с помощью «Найти клоны» сравните всю папку, на любой глубине, со списком с сайта. В GitHub подключение устанавливает GitHub App JayV в выбранный вами аккаунт или организацию, и оно получает доступ только к отмеченным там репозиториям; чтобы добавить другие, нажмите GitHub ещё раз. Проект организации не удаляется в приложении: owner или maintainer удаляет его на сайте, на вкладке «Проекты» организации, и он вместе с чатами исчезает из приложения всех участников, у которых он есть, а репозиторий остаётся в организации."$json$::jsonb),
  ('ja', 'docs.orgRepositories.usage', $json$"サイトで組織を開き、「リポジトリ」でプロバイダーを接続してリポジトリを追加します。アプリでは、組織のサイドメニューの「リポジトリ」に変更がすぐに反映されます。組織フォルダーを選び、足りないものをクローンし、「クローンを探す」でフォルダー全体をすべての階層でサイトの一覧と比較します。GitHub では、接続すると JayV の GitHub App が選んだアカウントまたは組織にインストールされ、そこで選んだリポジトリにだけアクセスします。追加するには、もう一度 GitHub をクリックしてください。組織のプロジェクトはアプリでは削除できません。owner または maintainer がサイトの組織の「プロジェクト」タブで削除すると、そのプロジェクトを持つすべてのメンバーのアプリからチャットごと消えます。リポジトリは組織に残ります。"$json$::jsonb),
  ('de', 'docs.orgRepositories.usage', $json$"Öffne auf der Website die Organisation, gehe zu Repositories, verbinde einen Anbieter und füge die Repositorys hinzu. In der App listet Repositories im Seitenmenü der Organisation sie auf, sobald sie sich ändern: Wähle den Organisationsordner, klone, was fehlt, und vergleiche mit Klone suchen den ganzen Ordner in jeder Tiefe mit der Liste der Website. Bei GitHub installiert das Verbinden die GitHub App von JayV im gewählten Konto oder in der gewählten Organisation, und sie erreicht nur die Repositorys, die du dort auswählst; um weitere hinzuzufügen, klicke erneut auf GitHub. Ein Projekt der Organisation wird nicht in der App gelöscht: Ein Owner oder Maintainer löscht es auf der Website im Tab Projekte der Organisation, und es verschwindet samt Chats aus der App aller Mitglieder, die es haben; das Repository bleibt in der Organisation."$json$::jsonb)
